Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <cstdio>
#include <iostream>
using namespace std;
long long int xrr[18];
int res=0;


void dfs(int ans,long long int rem,int p)
{
	//cout<<"ans: "<<ans<<" rem: "<<rem<<endl;
	if(ans>res)
		return;
	if(rem==0)
	{
		res=min(ans,res);
		return;
	}
	int need = rem/xrr[p];
	dfs(ans+(p*need++),rem-(need*xrr[p]),p-1);
	dfs(p*need+ans,need*xrr[p]-rem,p-1);
}

int main()
{
	long long int x;
	cin>>x;
	xrr[1]=1;
	for(int i=2;i<18;i++)
		xrr[i]=(10*xrr[i-1])+1;
	long long int xp=x;
	while(xp>0)
	{
		for(int i=1;i<18;i++)
			if(xrr[i]>xp)
			{
				//cout<<xrr[i-1]<<endl;
				res+=(i-1);
				xp-=xrr[i-1];
				break;
			}
	}
	//cout<<"init: "<<res<<endl;
	dfs(0,x,16);
	cout<<res<<endl;;
}

